export function AElement({
  text = "{{text}}",
  href = "{{href}}",
  target = "{{target}}",
  accent = "{{accent}}",
  underline = {{underline}},
}) {
  return (
    <p style={{ maxWidth: 420, font: "16px/1.6 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: "20px 22px", borderRadius: 10, margin: 0 }}>
      This is a real{" "}
      <a
        href={href}
        target={target}
        rel="noopener noreferrer"
        style={{ color: accent, fontWeight: 600, textDecoration: underline ? "underline" : "none", textUnderlineOffset: 3 }}
      >
        {text}
        {target === "_blank" && (
          <svg width="12" height="12" viewBox="0 0 24 24" aria-hidden="true" style={{ marginLeft: 3, verticalAlign: -1 }}>
            <path d="M14 5h5v5M19 5 10 14M7 5H5v14h14v-2" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        )}
      </a>{" "}
      anchor, taking you somewhere when clicked or tapped.
    </p>
  );
}
